-- ExamGrind verified daily current-affairs desk: 31 October 2026.
-- Every item below is independently checked against the linked competent official release.

insert into public.current_affairs_briefs (
  slug, published_on, title, summary, why_it_matters, background,
  source_title, source_url, source_publisher, source_published_on,
  prelims_takeaways, quick_check, visual_data, status, reviewed_at
) values
(
$$2026-10-31-national-social-security-boards$$, $$2026-10-31$$,
$$Government notifies National Social Security Boards for unorganised, gig and platform workers$$,
$$The Ministry of Labour and Employment notified the National Social Security Boards for unorganised workers and for gig and platform workers under the Code on Social Security. The Boards are to recommend suitable schemes, monitor Central schemes and review State-level record keeping and the use of the relevant fund.$$,
$$This is a major labour-welfare and platform-economy update. It helps students distinguish a statutory advisory and monitoring board from a benefit scheme itself, and connect gig work with the wider social-security framework.$$,
$$The Boards are chaired by the Union Labour and Employment Minister and include Central and State governments, aggregators, employers, worker organisations and other representatives. They must meet at least three times a year. A board can recommend or monitor schemes; it does not by itself automatically create a new cash entitlement for every worker.$$,
$$Government notifies National Social Security Board for Unorganised Workers and Gig & Platform Workers under the Labour Codes$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2330299&lang=1&reg=3$$,
$$Ministry of Labour & Employment / Press Information Bureau$$, $$2026-10-30$$,
$$["The Boards were notified under the Code on Social Security.","They cover unorganised workers as well as gig and platform workers.","Their functions include recommending and monitoring suitable Central schemes.","The Union Labour and Employment Minister presides over the Boards."]$$::jsonb,
$$[{"question":"Does notification of the Social Security Boards itself guarantee a new benefit to every platform worker?","answer":"No. The Boards recommend and monitor schemes; eligibility and benefits still depend on the applicable scheme and rules."}]$$::jsonb,
$${"title":"From worker category to social-security action","steps":["The Code identifies worker categories and institutional responsibilities.","The Boards recommend suitable welfare schemes.","Government schemes set eligibility and benefits.","The Boards monitor implementation and records."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-31-high-level-committee-banking-viksit-bharat$$, $$2026-10-31$$,
$$Centre constitutes High Level Committee on Banking for Viksit Bharat$$,
$$The Government constituted a six-month High Level Committee on Banking for Viksit Bharat to review the banking sector and recommend structural, institutional, regulatory and legislative reforms. The committee was announced in the 2026-27 Budget and is chaired by former Central Vigilance Commissioner Suresh N. Patel.$$,
$$The committee is an important institutional-development item for economy questions. It brings together banking regulation, financial inclusion, credit, priority-sector lending and digital-finance safeguards without changing any of those rules immediately.$$,
$$Its terms include reviewing prudential norms, legal and regulatory frameworks for banks including RRBs and cooperative banks, long-term capital needs, cost of capital, AI and cyber safeguards, and the Priority Sector Lending and Lead Bank frameworks. A committee recommendation is not the same thing as a notified RBI regulation or enacted law.$$,
$$The Government of India Constitutes the High Level Committee on Banking for Viksit Bharat$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2330598&lang=1&reg=3$$,
$$Ministry of Finance / Press Information Bureau$$, $$2026-10-30$$,
$$["The Committee has a six-month tenure.","It was announced in the Union Budget 2026-27.","Its remit includes RRBs, cooperative banks, DFIs and NBFCs.","It will review Priority Sector Lending and the Lead Bank Scheme."]$$::jsonb,
$$[{"question":"Does the committee's constitution itself amend RBI prudential norms?","answer":"No. It is tasked with reviewing and recommending reforms; any rule change would need the appropriate legal or regulatory process."}]$$::jsonb,
$${"title":"Committee-to-reform pathway","steps":["Government sets a review mandate.","The committee studies institutions, rules and evidence.","It submits recommendations.","Competent authorities decide whether and how to implement reforms."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-31-tamil-nadu-bharatnet-utilisation-agreement$$, $$2026-10-31$$,
$$Tamil Nadu signs BharatNet utilisation agreement under the State-led model$$,
$$Digital Bharat Nidhi, the Department of Telecommunications, the Tamil Nadu Government and TANFINET signed a utilisation agreement under the Amended BharatNet Programme. The arrangement provides for subsidy-supported use of the network for rural home-fibre connectivity and on-demand village connections.$$,
$$This connects digital public infrastructure with cooperative federalism and rural service delivery. It is useful for remembering BharatNet's last-mile goal and the renamed Digital Bharat Nidhi's role in universal-service support.$$,
$$The official release says the agreement is expected to facilitate more than five lakh rural home-fibre connections and on-demand connectivity to 4,767 villages in Tamil Nadu. BharatNet infrastructure and a service connection are not identical: the former enables the network, while the latter depends on rollout and operational delivery.$$,
$$Agreement Signed between DBN, DoT, Government of Tamil Nadu and TANFINET for Utilisation of BharatNet Network in Tamil Nadu under ABP$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2330586&lang=1&reg=3$$,
$$Ministry of Communications, Department of Telecommunications / Press Information Bureau$$, $$2026-10-30$$,
$$["The agreement uses the Amended BharatNet Programme's State-led model.","The parties include DBN, DoT, Tamil Nadu and TANFINET.","The release expects more than five lakh rural home-fibre connections.","Digital Bharat Nidhi is the renamed Universal Service Obligation Fund under the Telecommunications Act, 2023."]$$::jsonb,
$$[{"question":"What is Digital Bharat Nidhi in this agreement?","answer":"It is the universal-service support fund and attached DoT office formerly called the Universal Service Obligation Fund."}]$$::jsonb,
$${"title":"Rural broadband delivery","steps":["Universal-service funding supports network access.","BharatNet provides broadband infrastructure.","A State-led agreement assigns local rollout responsibilities.","Households and villages receive connections as implementation progresses."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-31-upi-online-bookings-uae-singapore$$, $$2026-10-31$$,
$$UPI online bookings open at attractions in the UAE and Singapore$$,
$$The Finance Ministry reported that UPI can now be used for online bookings at At the Top, Burj Khalifa in the UAE and Resorts World Sentosa in Singapore. The integrations follow partnerships by NPCI International Payments Limited with local payment partners.$$,
$$The item tests the internationalisation of India's digital-payment infrastructure. It also separates online merchant acceptance from currency convertibility, foreign-exchange regulation or universal acceptance in a destination country.$$,
$$NIPL is the international arm of NPCI. The UAE integration involves NEOPAY and Emaar Entertainment, while the Singapore integration uses FOMO Pay. The release lists ten countries where UPI is accepted and describes these as e-commerce extensions of earlier merchant-payment links.$$,
$$UPI Acceptance Enabled for Online Bookings at At the Top, Burj Khalifa and Resorts World Sentosa$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2330558&lang=1&reg=3$$,
$$Ministry of Finance / Press Information Bureau$$, $$2026-10-30$$,
$$["NIPL is the international arm of NPCI.","The UAE booking integration includes At the Top, Burj Khalifa.","The Singapore integration includes Resorts World Sentosa attractions.","The update concerns online bookings, building on existing cross-border payment links."]$$::jsonb,
$$[{"question":"Does this UPI announcement mean that UPI replaces all foreign-exchange rules for travellers?","answer":"No. It expands acceptance for named online purchases; it does not replace applicable payment, forex or merchant rules."}]$$::jsonb,
$${"title":"Cross-border payment acceptance","steps":["Indian payment infrastructure partners with a local network or merchant.","The merchant enables UPI for an approved use case.","A traveller initiates payment through a supported UPI app.","The transaction follows applicable cross-border payment arrangements."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-31-union-government-accounts-september$$, $$2026-10-31$$,
$$Union Government's September accounts show receipts at 50.3% of Budget Estimates$$,
$$The Finance Ministry released the consolidated Union Government accounts through September 2026. Total receipts were Rs 18,35,422 crore, or 50.3% of the corresponding 2026-27 Budget Estimates, while total expenditure was Rs 25,49,835 crore, or 47.7% of Budget Estimates.$$,
$$Monthly accounts are core public-finance material. They help students read Budget Estimates, tax and non-tax revenue, capital expenditure, tax devolution and subsidies without confusing a year-to-date figure with the final annual outcome.$$,
$$The release records Rs 6,99,409 crore transferred to States as tax devolution through September. It separates revenue expenditure from capital expenditure and reports Rs 6,54,547 crore of capital expenditure. Percentages of Budget Estimates describe progress against the budgeted full-year amount; they are not final fiscal-deficit figures.$$,
$$Monthly review of accounts of Government of India upto September 2026 (FY 2026-27)$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2330455&lang=1&reg=3$$,
$$Ministry of Finance / Press Information Bureau$$, $$2026-10-30$$,
$$["Receipts through September were Rs 18,35,422 crore, or 50.3% of BE.","Total expenditure was Rs 25,49,835 crore, or 47.7% of BE.","Tax devolution to States was Rs 6,99,409 crore through September.","Capital expenditure was Rs 6,54,547 crore."]$$::jsonb,
$$[{"question":"What does 50.3% of Budget Estimates mean in the September accounts?","answer":"It means receipts recorded through September equal 50.3% of the full-year amount budgeted for 2026-27, not that the year's accounts are closed."}]$$::jsonb,
$${"title":"Reading monthly Union accounts","steps":["The Budget sets annual estimates.","Receipts and expenditure accumulate during the year.","Monthly accounts compare year-to-date amounts with Budget Estimates.","Final annual fiscal outcomes are determined after the year closes."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-31-india-bleu-jec$$, $$2026-10-31$$,
$$India, Belgium and Luxembourg hold the 19th BLEU Joint Economic Commission$$,
$$The 19th India-Belgium-Luxembourg Economic Union Joint Economic Commission met in Luxembourg on 29 October to review trade and investment relations and identify areas for deeper economic cooperation. Discussions covered logistics, clean technology, financial services, digital transformation, healthcare and agro-food processing.$$,
$$This is a useful trade-diplomacy item. It reinforces that a Joint Economic Commission is a dialogue mechanism for reviewing cooperation and resolving market concerns; it is not itself a free-trade agreement or a treaty creating tariff preferences.$$,
$$BLEU is the Belgium-Luxembourg Economic Union. The participants also resolved to explore cooperation in aerospace, research, innovation, higher education and skills. The release records intended cooperation and dialogue, not a concluded market-access concession or investment commitment.$$,
$$19th India-BLEU Joint Economic Commission Session Held in Luxembourg to Strengthen Trade and Economic Cooperation$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2330346&lang=1&reg=3$$,
$$Ministry of Commerce & Industry / Press Information Bureau$$, $$2026-10-30$$,
$$["BLEU stands for the Belgium-Luxembourg Economic Union.","The 19th JEC was held in Luxembourg on 29 October 2026.","Priority sectors included logistics, renewable energy, FinTech and healthcare.","A JEC is a cooperation dialogue, not a free-trade agreement."]$$::jsonb,
$$[{"question":"Did the India-BLEU JEC itself create a new preferential trade agreement?","answer":"No. The release reports a review and dialogue forum; it does not announce a concluded preferential trade agreement."}]$$::jsonb,
$${"title":"Economic-dialogue mechanism","steps":["Partners convene an institutional dialogue.","They review trade and investment relations.","They identify sectoral opportunities and market concerns.","Separate negotiations or legal processes are needed for binding trade commitments."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-31-idbi-strategic-restructuring-process$$, $$2026-10-31$$,
$$Government clarifies valuation and bid process for IDBI Bank's strategic restructuring$$,
$$The Finance Ministry clarified the strategic-restructuring process for IDBI Bank, including the use of confidential bids, contemporaneous independent valuation and the Core Group of Secretaries on Disinvestment's role in handling procedural issues. It said the first bid round became functus officio after its bids were not approved.$$,
$$The clarification is valuable for disinvestment and banking questions because it distinguishes ownership, control, valuation and regulatory treatment. It also shows why a listed share price is not automatically the sole benchmark in a strategic transaction.$$,
$$The release says the CCEA had empowered the Core Group of Secretaries on Disinvestment to handle procedural difficulties in strategic disinvestment transactions. It also notes that RBI treats IDBI as a private bank for regulatory purposes after LIC acquired majority stakes in 2019, while the Government and LIC retain residual holdings. This is a process clarification, not a new banking licence or a completed sale announcement.$$,
$$Clarification on the Process of Strategic Restructuring of the IDBI Bank Ltd.$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2330284&lang=1&reg=3$$,
$$Ministry of Finance / Press Information Bureau$$, $$2026-10-29$$,
$$["The clarification concerns IDBI Bank's strategic restructuring process.","Independent advisers used separate valuation methodologies.","The first round became functus officio after bids were not approved.","RBI treats IDBI as a private bank for regulatory purposes after LIC's 2019 majority acquisition."]$$::jsonb,
$$[{"question":"Is a listed bank's market price always the only valuation benchmark in a strategic transaction?","answer":"No. The clarification describes confidential bids and contemporaneous independent valuations used to assess reasonableness."}]$$::jsonb,
$${"title":"Strategic-restructuring valuation","steps":["Qualified bidders submit confidential offers.","Independent advisers value the enterprise.","The competent government group compares bids and valuations.","It decides the procedural next step under delegated authority."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-31-pm-kisan-24th-instalment$$, $$2026-10-31$$,
$$PM-KISAN's 24th instalment transfers over Rs 18,690 crore to 9.34 crore farmers$$,
$$The government released the 24th instalment of PM-KISAN on 30 October, transferring more than Rs 18,690 crore by Direct Benefit Transfer to 9.34 crore eligible farmers. The linked official backgrounder records cumulative disbursements above Rs 4.64 lakh crore through 24 instalments.$$,
$$PM-KISAN is a high-value agriculture and welfare-scheme item. The update reinforces the distinction between an annual entitlement and an individual instalment, and between a centrally sponsored income-support scheme and a crop-insurance or procurement programme.$$,
$$PM-KISAN provides eligible landholding farmer families Rs 6,000 per year in three equal instalments of Rs 2,000. State governments identify and verify eligible households; the digital workflow uses Aadhaar-linked bank accounts, e-KYC and the Public Financial Management System. Receiving a transfer depends on eligibility and verified records, not merely on registering on the portal.$$,
$$24th Instalment of PM-KISAN$$,
$$https://www.pib.gov.in/PressNoteDetails.aspx?ModuleId=3&NoteId=160645&lang=2&reg=48$$,
$$PIB Research Unit / Ministry of Agriculture & Farmers Welfare$$, $$2026-10-30$$,
$$["The 24th instalment transferred over Rs 18,690 crore to 9.34 crore farmers.","PM-KISAN provides Rs 6,000 annually in three instalments.","Each instalment is Rs 2,000 for an eligible farmer family.","The scheme uses DBT, Aadhaar-linked accounts and e-KYC for delivery and verification."]$$::jsonb,
$$[{"question":"How much assistance does PM-KISAN provide annually to an eligible farmer family?","answer":"Rs 6,000 annually, paid in three equal instalments of Rs 2,000."}]$$::jsonb,
$${"title":"PM-KISAN benefit delivery","steps":["A State verifies eligible landholding farmer families.","Records are checked against Aadhaar and bank details.","The Department issues sanction orders through the payment workflow.","DBT credits the instalment to eligible beneficiaries."]}$$::jsonb, $$published$$, now()
)
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, why_it_matters = excluded.why_it_matters,
  background = excluded.background, source_title = excluded.source_title, source_url = excluded.source_url,
  source_publisher = excluded.source_publisher, source_published_on = excluded.source_published_on,
  prelims_takeaways = excluded.prelims_takeaways, quick_check = excluded.quick_check,
  visual_data = excluded.visual_data, status = excluded.status, reviewed_at = excluded.reviewed_at,
  updated_at = now();

insert into public.current_affairs_exam_tags (brief_id, exam_id)
select briefs.id, exams.id from public.current_affairs_briefs briefs cross join public.exams exams
where briefs.slug in (
$$2026-10-31-national-social-security-boards$$,
$$2026-10-31-high-level-committee-banking-viksit-bharat$$,
$$2026-10-31-tamil-nadu-bharatnet-utilisation-agreement$$,
$$2026-10-31-upi-online-bookings-uae-singapore$$,
$$2026-10-31-union-government-accounts-september$$,
$$2026-10-31-india-bleu-jec$$,
$$2026-10-31-idbi-strategic-restructuring-process$$,
$$2026-10-31-pm-kisan-24th-instalment$$
) and exams.slug in ($$cuet$$, $$ssc-cgl$$, $$uppsc-ro-aro$$, $$up-secretariat-ro-aro$$)
on conflict do nothing;
